<!doctype html><html><head><meta charset="utf-8"><title>VEDAIRO Products</title><meta name="csrf-token" content="<?=e(csrf_token())?>"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="container py-4"><h1>Products</h1><form class="row g-2 mb-3"><div class="col"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search"></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><form method="post" action="/products" class="row g-2 mb-4"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><div class="col"><input class="form-control" name="name" placeholder="Name" required></div><div class="col"><input class="form-control" name="price" type="number" step="0.01" placeholder="Price" required></div><div class="col"><input class="form-control" name="stock" type="number" placeholder="Stock" required></div><div class="col-auto"><button class="btn btn-success">Add</button></div></form><table class="table"><thead><tr><th>Name</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody><?php foreach($p->items as $x): ?><tr><td><?=e($x['name'])?></td><td><?=e($x['price'])?></td><td><?=e($x['stock'])?></td><td><button class="btn btn-sm btn-danger del" data-id="<?=e($x['id'])?>">Delete</button><button class="btn btn-sm btn-warning addcart ms-1" data-id="<?=e($x['id'])?>">Cart</button></td></tr><?php endforeach;?></tbody></table><?=$p->links()?><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script>$('.del').click(function(){let id=$(this).data('id');$.ajax({url:'/products/'+id,method:'DELETE',headers:{'X-CSRF-TOKEN':$('meta[name=csrf-token]').attr('content')},success:()=>location.reload()});});$('.addcart').click(function(){ $.post('/cart/add',{_token:$('meta[name=csrf-token]').attr('content'),product_id:$(this).data('id'),qty:1},()=>alert('Added to cart'));});</script></body></html>
